# Parse the actual edges
actual_edges = []
for line in actual_edges_text.strip().split('\n'):
    if '->' in line:
        parts = line.split('->')
        source = parts[0].strip()
        target = parts[1].strip()
        actual_edges.append((source, target))

print(f"Total edges found: {len(actual_edges)}")

# Find parents of c4ca4238a0
target_node = "c4ca4238a0"
parents = []
for source, target in actual_edges:
    if target == target_node:
        parents.append(source)

print(f"\nParents of {target_node}: {sorted(set(parents))}")
print(f"\nAll edges where target is {target_node}:")
for source, target in actual_edges:
    if target == target_node:
        print(f"  {source} -> {target}")
